contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address spender, uint256 firstVal, uint256 secondVal) public {
        require(spender != address(0));
        require(firstVal > 0);
        require(secondVal > 0);

        bool r1 = c.approve(spender, firstVal); if (__ESBMC_reverted()) return;
        uint256 a1 = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        bool r2 = c.approve(spender, secondVal); if (__ESBMC_reverted()) return;
        uint256 a2 = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        bool r3 = c.approve(spender, 0); if (__ESBMC_reverted()) return;
        uint256 a3 = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        bool r4 = c.approve(spender, secondVal); if (__ESBMC_reverted()) return;
        uint256 a4 = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;

        assert(r1 && r2 == false && a1 == firstVal && a2 == firstVal
            && r3 && a3 == 0 && r4 && a4 == secondVal);
    }

    receive() external payable {}
}

